  public static void deferredUiWorkReleasesModelAccess(final Project project) {
    Assert.assertFalse("This regression must run outside model access", project.getRepository().getModelAccess().canRead());
    final CountDownLatch completed = new CountDownLatch(1);
    final AtomicReference<String> failure = new AtomicReference<String>();
    final Application application = ApplicationManager.getApplication();
    final ModalityState modality = ModalityState.nonModal();
    final Runnable ui = () -> verifyUnlockedUi(project, completed, failure);
    application.invokeAndWait(() -> project.getRepository().getModelAccess().executeCommand(() -> application.invokeLater(ui, modality)));
    try {
      Assert.assertTrue("Deferred UI callback must complete", completed.await(10, TimeUnit.SECONDS));
    } catch (InterruptedException exception) {
      Thread.currentThread().interrupt();
      throw new AssertionError(exception);
    }
    Assert.assertNull(failure.get(), failure.get());
  }
  private static void verifyUnlockedUi(final Project project, CountDownLatch completed, AtomicReference<String> failure) {
    try {
      DiffPasteUI.requireUnlockedDialogs(project);
      final CountDownLatch reader = new CountDownLatch(1);
      Thread worker = new Thread(() -> project.getRepository().getModelAccess().runReadAction(() -> reader.countDown()), "plaintextgen-model-reader");
      worker.start();
      if (!(reader.await(5, TimeUnit.SECONDS))) {
        failure.set("A background reader was blocked during deferred UI work");
      }
    } catch (IllegalStateException exception) {
      failure.set(exception.toString());
    } catch (InterruptedException exception) {
      Thread.currentThread().interrupt();
      failure.set(exception.toString());
    } finally {
      completed.countDown();
    }
  }

